import json
import sys
import time
import urllib.request
import urllib.error

BASE = "http://localhost:8080"
LOG = []


def req(method, path, token=None):
    headers = {}
    if token:
        headers["Authorization"] = "Bearer " + token
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")


def get_token():
    while True:
        status, headers, body = req("POST", "/token")
        if status == 200:
            return json.loads(body)["token"]
        LOG.append(("token", status, body[:200]))
        wait_for(status, headers, body)


def wait_for(status, headers, body):
    ra = headers.get("Retry-After")
    if ra is not None:
        try:
            secs = float(ra)
        except ValueError:
            secs = 5
        LOG.append(("retry-after", status, ra))
        time.sleep(secs)
    else:
        time.sleep(2)


def get_json(path, token_holder):
    while True:
        status, headers, body = req("GET", path, token_holder[0])
        if status == 200:
            return json.loads(body)
        LOG.append((path, status, body[:200]))
        if status == 401:
            token_holder[0] = get_token()
            continue
        if status == 404:
            return None
        wait_for(status, headers, body)


def main():
    token = [get_token()]
    orders = []
    page_path = "/orders?page=1"
    pages_seen = 0
    total_pages = None
    while page_path:
        data = get_json(page_path, token)
        pages_seen += 1
        total_pages = data["total_pages"]
        for item in data["items"]:
            orders.append(item)
        page_path = data["next"]
    customers = {}
    needed = sorted({o["customer_id"] for o in orders})
    for cid in needed:
        c = get_json("/customers/" + cid, token)
        customers[cid] = c
    with open("/tmp/recon/raw.json", "w") as f:
        json.dump({"orders": orders, "customers": customers,
                   "pages_seen": pages_seen, "total_pages": total_pages}, f)
    print("pages_seen", pages_seen, "total_pages", total_pages,
          "items", len(orders), "customers", len(customers))
    print("log events", len(LOG))
    for ev in LOG[:20]:
        print(ev)


if __name__ == "__main__":
    sys.exit(main())

